{noformat}import csv
import re

def batch(iterable, n=1):
    l = len(iterable)
    for ndx in range(0, l, n):
        yield iterable[ndx:min(ndx + n, l)]

def build_case_query(ids, last_update):

    q = f"""""";
    for i in range(len(ids)):
        s = f""" WHEN id = {ids[i]} THEN '{last_update[i]}' """
        q += s;
    return q;


def build_update_query(table_name, case_query, ids):
    return f"""UPDATE {table_name} SET delivery_price = 0, last_update = CASE {case_query} END  WHERE id IN ({', '.join(ids)});""".replace("\n", " ");


def write_query_to_file(table_name, ids, last_update, output_file):
    case=build_case_query(ids, last_update);
    update_query = build_update_query(table_name, case, ids);
    output_file.write(update_query + "\n")




